    61  prependIncompleteChunk(UA_Connection *connection, UA_ByteString *message) {
    62      /* Allocate the new message buffer */
    63      size_t length = connection->incompleteMessage.length + message->length;
    64      UA_Byte *data = (UA_Byte*)UA_realloc(connection->incompleteMessage.data, length);
