    88  static UA_StatusCode
    89  processChunk(UA_Connection *connection, void *application,
    90               UA_Connection_processChunk processCallback,
    91               const UA_Byte **posp, const UA_Byte *end, UA_Boolean *done) {
    92      const UA_Byte *pos = *posp;
    93      size_t length = (uintptr_t)end - (uintptr_t)pos;
    94
    95      /* At least 8 byte needed for the header. Wait for the next chunk. */
    96      if(length < 8) {
    97          bufferIncompleteChunk(connection, pos, end);
    98          *done = true;
    99          return UA_STATUSCODE_GOOD;
   100      }
   101
   102      /* Check the message type */
   103      UA_MessageType msgtype = (UA_MessageType)((UA_UInt32)pos[0] + ((UA_UInt32)pos[1] << 8) +
   104          ((UA_UInt32)pos[2] << 16));
   105      if(msgtype != UA_MESSAGETYPE_MSG && msgtype != UA_MESSAGETYPE_ERR &&
   106         msgtype != UA_MESSAGETYPE_OPN && msgtype != UA_MESSAGETYPE_HEL &&
   107         msgtype != UA_MESSAGETYPE_ACK && msgtype != UA_MESSAGETYPE_CLO) {
   108          /* The message type is not recognized */
   109          return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
   110      }
   111
   112      UA_Byte isFinal = pos[3];
   113      if(isFinal != 'C' && isFinal != 'F' && isFinal != 'A') {
   114          /* The message type is not recognized */
   115          return UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
   116      }
   117
   118      UA_UInt32 chunk_length = 0;
   119      UA_ByteString temp = { 8, (UA_Byte*)(uintptr_t)pos }; /* At least 8 byte left */
   120      size_t temp_offset = 4;
   121      /* Decoding the UInt32 cannot fail */
   122      UA_UInt32_decodeBinary(&temp, &temp_offset, &chunk_length);
   123
   124      /* The message size is not allowed */
   125      if(chunk_length < 16 || chunk_length > connection->localConf.recvBufferSize)
   126          return UA_STATUSCODE_BADTCPMESSAGETOOLARGE;
   127
   128      /* Wait for the next packet to process the complete chunk */
   129      if(chunk_length > length) {
   130          bufferIncompleteChunk(connection, pos, end);
   131          *done = true;
   132          return UA_STATUSCODE_GOOD;
   133      }
   134
   135      /* Process the chunk; forward the position pointer */
   136      temp.length = chunk_length;
   137      *posp += chunk_length;
   138      *done = false;
   139      return processCallback(application, connection, &temp);
